#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Task 446 — обновление системного промта kip8: шапка post-446
(перенос), v484→v485, тесты 4697→4724 (kip8test 4691→4718),
формат бампа v485→v486."""
import io

P = '/home/z/my-project/kip8/Системный_промт_для_приложения_КИПиА.md'
s = io.open(P, encoding='utf-8').read()

NEW_HEAD = '''> **Версия документа:** 2026-09-29 (post-Task 446: ПЕРЕНОС Task 446 из kip8test@ea79439 в боевой kip8 ОДНИМ инкрементом SW kipia-v484→v485 — регламент Task 441 «Переноси все изменения в боевой репозиторий kip8». СОСТАВ (заявка: «На страницах архива Отпуска/Инструктажи/СИЗ/Мероприятия убери столбцы id и Таб. №. На странице Инструктажи отсортируй строки по фамилиям. На всех страницах фон групп строк по фамилиям сделай зеброй»): листы Excel-архива без технических колонок + сортировка по фамилиям + зебра по группам строк; ПОЛНОСТЬЮ КЛИЕНТСКАЯ задача — WorkSchedule.gs/PPEInit.gs/Code.gs НЕ тронуты (srvVer 427), серверные шаги НЕ требуются, Ctrl+Shift+R ×1–2. (1) КОЛОНКИ id И «Таб. №» УДАЛЕНЫ из листов «Отпуска» (ФИО/Часть/даты/Дней/Комментарий), «Инструктажи» (ФИО/Тип/Тема/Дата проведения/Выполнено/Просрочен/Комментарий), «СИЗ» (Работник/Должность/Наименование/выдача/изготовление/срок/окончание/Примечание), «Мероприятия» (ФИО/Тип/Тема/даты/Длительность/Комментарий) — работник ПЕРВОЙ колонкой; лист «Работники» НЕ тронут (справочник, «Таб. №» жив); дедуп записей — по исходным записям, не тронут. (2) «ИНСТРУКТАЖИ» — СОРТИРОВКА ПО ФАМИЛИЯМ (ФИО → дата → id, приём «Отпусков»; записи работника ПОДРЯД, внутри группы даты asc); «Мероприятия» — прежняя по дате, «СИЗ» — прежняя по таб.№→наименование, «Отпуска» — прежняя ФИО→дата; карточки/шахматка (_wtabYearRecords) НЕ тронуты. (3) ЗЕБРА НА ВСЕХ ЛИСТАХ — НОВЫЙ _wsXlsZebraGroups(rows, personHeader): колонка работника по заголовку («ФИО»/«Работник»), заливка #F2F2F2 чередуется ПРИ СМЕНЕ фамилии, внутри группы строки одной заливки, первая группа — БЕЗ заливки; styles fills 4 (+FFF2F2F2) / cellXfs 3 (fillId=3, s="2"); НЕПРЕРЫВНОСТЬ ПОЛОСЫ: пустая ячейка залитой строки — ячейка с одним стилем (полоса без «дыр»). МЕТОД (scripts/task446-transfer.py, паттерн 292/429/437/441-445): index.html — kip8test@ea79439 + 14 де-изоляций, «дифф диффов» — репо-дифф 55 строк == эталону, дифф задач идентичен обоим репо, kip8test-упоминаний 4 исторических, kipia-test-v 0; WorkSchedule.gs/PPEInit.gs — синхронны (446 не трогала, проверено); Code.gs — kip8-версия не тронута (исторически отличается); тесты 154 test-*.js с маппингом kipia-test-v670→kipia-v485 (446) / v671→v486 (103) / v665→v481 (2) / v663+v660+v634/v640/v641/v642→v478 (6), test-task344 v484→v485 (3), run-all +344+438–446. ПРОГОН: 4724 passed / 0 failed (154 файла = паритет kip8test 4718/0 + 6 task344); node --check sw.js OK; SMOKE браузер task446-smoke-k8.py 16/16 (порт 8956, ключи kip8 без префикса: график, «Общая», «Скачать архив», РЕАЛЬНОЕ скачивание .xlsx — ZIP 10 частей, workbook 5 листов, шапки 4 листов БЕЗ id/«Таб. №» + «Работники» с «Таб. №», «Инструктажи» Петров→Федосов×2 по фамилиям, ЗЕБРА всех 5 листов по группам фамилий, залитая строка — ВСЕ 8 ячеек (полоса без «дыр»), styles fills 4/F2F2F2/cellXfs 3, тост, 0 JS-ошибок). Полнота функциональности — по прогонам kip8test (тесты 4718/0, браузер 31/31, openpyxl 13/13, пиксельный пруф, VLM ×3) + идентичность диффа задач. ТЕКУЩЕЕ СОСТОЯНИЕ: kip8 SW `kipia-v485` (guard v486), тесты 4724/0 (154 файла, включая kip8-специфичный test-task344.js); kip8test @ea79439, SW `kipia-test-v670` (guard v671), тесты 4718/0 (154 файла); десктопы kip8test-desktop/kip8-desktop — CI-автосинк при пуше index.html. СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 447 (в обоих репо).)
'''

# 1) новая шапка, прежняя → «(предыдущая)»
lines = s.split('\n')
assert lines[2].startswith('> **Версия документа:** 2026-09-29 (post-Task 445'), \
    'строка 3 не post-445 (kip8)'
old_head = lines[2]
demoted = old_head.replace(
    '> **Версия документа:**', '> **Версия документа (предыдущая):**', 1)
lines[2] = NEW_HEAD.rstrip('\n') + '\n' + demoted
s = '\n'.join(lines)

# 2) текущая версия кэша
old = '> **Текущая версия кэша:** `kipia-v484`'
new = '> **Текущая версия кэша:** `kipia-v485`'
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)

# 3) формат бампа
old = 'kipia-v484` → `kipia-v485` (для kip8)'
new = 'kipia-v485` → `kipia-v486` (для kip8)'
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)

# 4) счётчик тестов
old = '# Ожидается: 4697 passed, 0 failed (kip8; в kip8test — 4691 passed, 0 failed)'
new = '# Ожидается: 4724 passed, 0 failed (kip8; в kip8test — 4718 passed, 0 failed)'
assert s.count(old) == 1, s.count(old)
s = s.replace(old, new)

io.open(P, 'w', encoding='utf-8').write(s)
print('OK: промт kip8 post-446 (шапка + v485 + 4724/4718 + бамп v486)')
